import{_ as t,o as d,c as o,a2 as s}from"./chunks/framework.CmvPqeTF.js";const S=JSON.parse('{"title":"架构总览","description":"","frontmatter":{},"headers":[],"relativePath":"dev/architecture.md","filePath":"dev/architecture.md","lastUpdated":1791351888000}'),a={name:"dev/architecture.md"};function c(n,e,r,i,l,p){return d(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>vShell 是 Wails 3 桌面应用：<strong>Go 后端</strong>承担全部系统能力（SSH / SFTP / 文件 / 数据库），<strong>Vue 3 前端</strong>纯 UI。两者通过「服务绑定（同步调用）+ Wails Events（流式推送）」双通道通信。</p><hr><h2 id="_1-总体结构" tabindex="-1">1. 总体结构 <a class="header-anchor" href="#_1-总体结构" aria-label="Permalink to &quot;1. 总体结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────── main.go ────────────────────────────────┐</span></span>
<span class="line"><span>│  embed frontend/dist · 原生菜单（menu:settings/save/close-tab）          │</span></span>
<span class="line"><span>│  窗口：1280×800 · macOS 隐藏标题栏(30px) · EnableFileDrop                │</span></span>
<span class="line"><span>│  Services: [AppService]                                                  │</span></span>
<span class="line"><span>└───────────────────────────────────┬──────────────────────────────────────┘</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>┌──────────────────────────── internal/app.AppService ────────────────────┐</span></span>
<span class="line"><span>│  wailsApp · db · sshManager · sftpManager · fwdManager · monitors{}    │</span></span>
<span class="line"><span>│                                                                         │</span></span>
<span class="line"><span>│  服务绑定方法（81 个）：连接/分组/快捷命令/端口转发/SFTP/密钥/sshconfig/   │</span></span>
<span class="line"><span>│  本地FS/证书 · 生命周期：ServiceStartup / ServiceShutdown               │</span></span>
<span class="line"><span>│  连接管理：ConnectSSH / DisconnectSSH / DisconnectSession               │</span></span>
<span class="line"><span>└───┬──────────┬──────────────┬──────────────┬──────────┬────────────────┘</span></span>
<span class="line"><span>    │          │              │              │          │</span></span>
<span class="line"><span>┌───▼───┐  ┌───▼───────┐  ┌───▼─────────┐  ┌─▼────────┐ │</span></span>
<span class="line"><span>│ ssh   │  │ sftp      │  │ portforward │  │ db       │ │</span></span>
<span class="line"><span>│ 会话/ │  │ 传输并发池 │  │ 本地转发     │  │ SQLite   │ │</span></span>
<span class="line"><span>│ 监控  │  │ (cap 3)   │  │             │  │ WAL 单连接│ │</span></span>
<span class="line"><span>└───────┘  └───────────┘  └─────────────┘  └──────────┘ │</span></span>
<span class="line"><span>┌───────────┐  ┌───────────┐                             │</span></span>
<span class="line"><span>│ crypto    │  │ cert      │◄────────────────────────────┘</span></span>
<span class="line"><span>│ AES-GCM   │  │ acme.sh   │  经 SSH/SFTP 驱动远程服务器上的</span></span>
<span class="line"><span>│ .enc_key  │  │ 远程编排  │  acme.sh（检测/安装/签发/续签/部署）</span></span>
<span class="line"><span>└───────────┘  └───────────┘</span></span></code></pre></div><h2 id="_2-前端结构-frontend-src" tabindex="-1">2. 前端结构（frontend/src） <a class="header-anchor" href="#_2-前端结构-frontend-src" aria-label="Permalink to &quot;2. 前端结构（frontend/src）&quot;">​</a></h2><p>无路由的单页面组合（vue-router 依赖存在但未使用路由表）。界面为<strong>岛屿（Islands）设计语言</strong>——画布 + 浮动圆角岛，岛间统一 6px 接缝（规范见<a href="./../ui/vshell-design-language.html">岛屿设计语言</a>），自上而下：</p><table tabindex="0"><thead><tr><th>层</th><th>组件 / 模块</th></tr></thead><tbody><tr><td>岛屿壳</td><td><code>shell/AppShell.vue</code> —— 画布级布局，集中持有各面板头部动作</td></tr><tr><td>顶部工具栏岛</td><td><code>shell/ToolbarIsland.vue</code> —— 唯一窗口拖拽区、主题 / 语言切换、连接进度条</td></tr><tr><td>左条 + 左工具窗岛</td><td><code>shell/LeftStripe.vue</code>（40px 通高图标条：连接 / 密钥 / SSH 配置 / 端口转发 / 证书 + SFTP / 监控 / 设置）；<code>shell/ToolWindow.vue</code>（可收起）承载 <code>sidebar/</code>（连接树、连接表单）、<code>keys/</code>、<code>config/</code>、<code>panels/</code>（端口转发）、<code>cert/</code>（证书管理）</td></tr><tr><td>中心岛（永不收起）</td><td><code>shell/EditorIsland.vue</code> + <code>shell/EditorTabs.vue</code>（超宽标签按 IDEA 方式折叠进下拉）→ <code>terminal/XTerminal.vue</code> / <code>EditorTab.vue</code>（Monaco）；所有会话保活堆叠（visibility 切换，不销毁）</td></tr><tr><td>底部工具窗岛</td><td><code>monitor/MonitorPanel.vue</code>（ECharts）、<code>sftp/SFTPArea.vue</code></td></tr><tr><td>状态栏岛</td><td><code>shell/StatusBarIsland.vue</code> —— 连接四态与会话数、传输摘要、面板快速开关</td></tr><tr><td>状态</td><td>Pinia：connection / terminal / sftp / monitor / settings / layout / transfers / sshkey / sshconfig / cert（10 个）</td></tr><tr><td>组合式</td><td><code>useTerminalManager.ts</code>（全局 stdout 分发）、<code>useShortcuts.ts</code>、<code>useDragTransfer.ts</code>（应用内拖拽）</td></tr></tbody></table><h2 id="_3-双通道通信" tabindex="-1">3. 双通道通信 <a class="header-anchor" href="#_3-双通道通信" aria-label="Permalink to &quot;3. 双通道通信&quot;">​</a></h2><h3 id="_3-1-服务绑定-同步-请求-响应" tabindex="-1">3.1 服务绑定（同步，请求 / 响应） <a class="header-anchor" href="#_3-1-服务绑定-同步-请求-响应" aria-label="Permalink to &quot;3.1 服务绑定（同步，请求 / 响应）&quot;">​</a></h3><p>CRUD 与一次性操作走 <code>application.NewService(AppService)</code> 绑定，前端调用生成于 <code>frontend/bindings/vshell/internal/app/appservice.ts</code>（81 个函数，分布在 <code>app.go</code> / <code>cert.go</code> / <code>sshconfig.go</code>）。典型分组：</p><table tabindex="0"><thead><tr><th>分组</th><th>代表方法</th></tr></thead><tbody><tr><td>连接 / 分组</td><td><code>ListConnections</code> <code>CreateConnection</code> <code>MoveConnection</code> <code>GetPassword</code> …</td></tr><tr><td>SSH 生命周期</td><td><code>ConnectSSH</code> <code>DisconnectSSH</code> <code>DisconnectSession</code> <code>StartMonitor</code> <code>StopMonitor</code></td></tr><tr><td>SFTP</td><td><code>SFTPReadDir</code> <code>SFTPUpload</code> <code>SFTPDownload</code> <code>SFTPDelete</code> <code>SFTPReadFileContent</code> <code>SFTPCancelTransfers</code></td></tr><tr><td>密钥</td><td><code>ListSSHKeys</code> <code>GenerateSSHKey</code> <code>SaveSSHKey</code> <code>GetSSHKeyUsage</code> …</td></tr><tr><td>sshconfig</td><td><code>ReadSSHConfig</code> <code>WriteSSHConfig</code> <code>GetSSHConfigImportCandidates</code> <code>ImportSSHConfigHosts</code> …</td></tr><tr><td>本地 FS</td><td><code>GetHomeDir</code> <code>ListLocalDir</code> <code>ReadLocalFileContent</code> <code>OpenInFileManager</code> …</td></tr><tr><td>端口转发</td><td><code>CreatePortForward</code> <code>StartPortForward</code> <code>StopPortForward</code> <code>ListRunningPortForwards</code> …</td></tr><tr><td>证书</td><td><code>ListCertTasks</code> <code>CreateCertTask</code> <code>StartCertIssue</code> <code>StartCertRenew</code> <code>ListDNSProviders</code> <code>DetectCertEnvironment</code> <code>ListRemoteCerts</code> <code>GetCertServerLog</code> <code>CancelCertOp</code> …</td></tr></tbody></table><h3 id="_3-2-wails-events-流式-推送" tabindex="-1">3.2 Wails Events（流式 / 推送） <a class="header-anchor" href="#_3-2-wails-events-流式-推送" aria-label="Permalink to &quot;3.2 Wails Events（流式 / 推送）&quot;">​</a></h3><p><strong>后端 → 前端</strong>（<code>wailsApp.Event.Emit</code>）：</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>用途</th></tr></thead><tbody><tr><td><code>terminal:stdout</code> / <code>terminal:stderr</code></td><td><code>{sessionID, data}</code></td><td>终端输出流</td></tr><tr><td><code>terminal:closed</code></td><td><code>{sessionID}</code></td><td>会话结束</td></tr><tr><td><code>monitor:stats</code> / <code>:disk</code> / <code>:load</code> / <code>:processes</code> / <code>:netconns</code></td><td><code>{connectionID, …}</code></td><td>监控指标（2s/10s/5s/5s/10s）</td></tr><tr><td><code>sftp:progress</code></td><td><code>TransferProgress</code></td><td>传输进度</td></tr><tr><td><code>sftp:transfer-done</code></td><td><code>{direction, connectionID}</code></td><td>传输 / 删除完成</td></tr><tr><td><code>sftp:upload:error</code> / <code>sftp:download:error</code></td><td>string</td><td>传输失败</td></tr><tr><td><code>cert:log</code></td><td><code>{taskID?/opID?, connectionID, stream, line, ts}</code></td><td>acme.sh 操作日志逐行流式回传</td></tr><tr><td><code>cert:stage</code></td><td><code>{taskID?/opID?, connectionID, stage, status, error?}</code></td><td>证书编排阶段推进（start / ok / fail）</td></tr><tr><td><code>menu:settings</code> / <code>menu:save</code> / <code>menu:close-tab</code></td><td>nil</td><td>原生菜单动作</td></tr><tr><td><code>native:file-drop</code></td><td><code>{files, targetId}</code></td><td>系统文件拖入</td></tr></tbody></table><p><strong>前端 → 后端</strong>（<code>Events.Emit</code>，<code>app.ServiceStartup</code> 注册监听）：</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>处理</th></tr></thead><tbody><tr><td><code>terminal:stdin</code></td><td><code>{sessionID, data}</code></td><td><code>WriteStdin</code></td></tr><tr><td><code>terminal:resize</code></td><td><code>{sessionID, rows, cols}</code></td><td><code>WindowChange</code></td></tr></tbody></table><blockquote><p>红线：终端数据<strong>必须</strong>走 Events，同步 Call 会把每字节 I/O 变成跨语言往返。<code>localfs:*</code> / <code>sftp:upload</code> / <code>sftp:download</code> 等旧事件通道已废弃改绑定调用，后端监听仍在（遗留双通道）。</p></blockquote><h2 id="_4-关键连接管理" tabindex="-1">4. 关键连接管理 <a class="header-anchor" href="#_4-关键连接管理" aria-label="Permalink to &quot;4. 关键连接管理&quot;">​</a></h2><p><code>ssh.Manager</code> 维护三层映射：<code>clients[connectionID]*ssh.Client</code>、<code>sessions[sessionID]*Session</code>、<code>connSess[connectionID][]sessionID</code>。</p><ul><li>同一连接的<strong>终端、SFTP、监控、端口转发复用同一条 SSH TCP 连接</strong></li><li>连接级断开（<code>Disconnect</code>）依次：停监控 → 关 SFTP → 关全部会话与 client → 停全部转发</li><li>端口转发可在无终端时按需 <code>EnsureClient</code> 建立纯转发连接，空闲后 <code>RemoveClient</code> 回收</li><li>会话通道数受服务端 <code>MaxSessions</code>（OpenSSH 默认 10）限制：超限时 <code>NewSession()</code> 报错经 <code>friendlySessionError</code> 转译为可操作提示（关闭未用标签或调大 sshd_config），<strong>不再误关共享连接</strong>（问题 0010，含回归测试）</li></ul><p>认证构建（<code>buildSSHConfig</code>）：密码 / 私钥（含口令）/ Keyboard-Interactive 三种已实现；Agent 与跳板机未实现。<code>HostKeyCallback</code> 当前为 <code>ssh.InsecureIgnoreHostKey()</code>（不校验主机指纹），超时 10s。</p><h2 id="_5-证书管理-internal-cert" tabindex="-1">5. 证书管理（<code>internal/cert</code>） <a class="header-anchor" href="#_5-证书管理-internal-cert" aria-label="Permalink to &quot;5. 证书管理（\`internal/cert\`）&quot;">​</a></h2><p>通过 SSH 在远程服务器上驱动 acme.sh，编排「检测 → 安装 → 签发 / 续签 → 部署证书 → 检查 cron → 完成」的阶段流：</p><ul><li><strong>编排器</strong>（<code>issue.go</code> / <code>manager.go</code>）：每阶段经 <code>cert:stage</code> 事件汇报进度，远程命令输出逐行经 <code>cert:log</code> 流式回传，并持久化到 <code>cert_tasks.last_log</code></li><li><strong>续签刻意走 <code>--issue --force</code></strong>：<code>--renew</code> 会重放服务器旧 conf 里的插件配置，vShell 侧更换 DNS 提供商 / 凭据不会生效</li><li><strong>DNS 凭据</strong>：AES 加密存储、<code>json:&quot;-&quot;</code> 永不出后端；签发时经 SFTP 写临时 env 文件（0600，命令结束自删）</li><li><strong>DNS 提供商注册表</strong>（<code>dnsproviders.go</code>）：aliyun / dnspod / tencent / cloudflare / custom，含凭据字段校验</li><li>应用启动时 <code>resetInterruptedCertTasks</code> 把上次被中断的「执行中」任务复位</li></ul><h2 id="_6-已知实现边界" tabindex="-1">6. 已知实现边界 <a class="header-anchor" href="#_6-已知实现边界" aria-label="Permalink to &quot;6. 已知实现边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>状态</th></tr></thead><tbody><tr><td>SSH Agent 认证、跳板机</td><td>未实现（连接时报错）</td></tr><tr><td>端口转发</td><td>仅 <code>local</code>；<code>remote</code> / <code>dynamic</code> 启动即报错</td></tr><tr><td>端口转发「自动启动」</td><td>仅存储勾选，无自动拉起路径</td></tr><tr><td>ZMODEM</td><td>纯桩（<code>zmodem.Detector</code>，无调用方）</td></tr><tr><td>终端 stderr 事件</td><td>后端发射、前端未消费</td></tr><tr><td>SFTP 重命名 / chmod</td><td>未实现</td></tr><tr><td>快捷命令</td><td>后端 API + 表齐备，前端无 UI</td></tr><tr><td>DB 迁移</td><td>无版本表，<code>CREATE TABLE IF NOT EXISTS</code> + 容错 <code>ALTER</code></td></tr></tbody></table><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./terminal-io.html">终端 I/O 数据流</a></li><li><a href="./storage-crypto.html">数据存储与加密</a></li><li><a href="./development.html">构建与开发环境</a></li></ul>`,30)])])}const u=t(a,[["render",c]]);export{S as __pageData,u as default};
